import {RequestGate,probeService,serviceUrl,ServiceError} from './service.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={valid:'有效',missing:'未填写',invalid:'格式无效'};
export function createServiceSettings({getConfig,save,modal,toast}){
 return function show(){const config=getConfig(),gate=new RequestGate();const d=modal('创作助手设置',`<div class="service-settings"><p>默认离线即可创作。只有明确生成时才发送描述与音符；检查配置只读取状态，不调用模型、不发送工程。</p><label class="modal-label" for="settings-mode">生成方式</label><select id="settings-mode"><option value="offline" ${config.mode==='offline'?'selected':''}>离线灵感引擎（免费，本机运行）</option><option value="llm" ${config.mode==='llm'?'selected':''}>我的 LLM 服务</option></select><div id="llm-settings" ${config.mode==='llm'?'':'hidden'}><label class="modal-label" for="settings-endpoint">编曲服务地址</label><input id="settings-endpoint" type="text" value="${escape(config.endpoint)}" placeholder="/api/compose" maxlength="1000"><small>这是芽音协议地址，不是模型厂商 /v1/chat/completions；后者只在服务端配置。</small><label class="modal-label" for="settings-model">模型名称（可留空，使用服务默认值）</label><input id="settings-model" type="text" value="${escape(config.model)}" placeholder="由服务端配置" maxlength="120"><label class="modal-label" for="settings-status">状态服务地址（可选）</label><input id="settings-status" type="text" value="${escape(config.statusEndpoint??'/api/llm/status')}" placeholder="同一服务的 /api/llm/status" maxlength="1000"><small>自有服务请填写它提供的状态地址，须与编曲服务同源。不支持状态接口仍可保存设置并手动生成，但不会宣称连接已验证。</small><div class="service-probe-tools"><button class="quiet" id="check-service">检查配置（不调用模型）</button><button class="quiet" id="cancel-service-check" hidden>停止检查</button></div><div id="service-probe-result" class="service-probe-result" role="status" hidden></div><details class="service-setup"><summary>第一次连接？看三步设置</summary><ol><li>源码本机版：复制 .env.example 为 .env，在服务端填自己的 LLM_API_URL、LLM_MODEL，需鉴权时填 LLM_API_KEY；重启本机服务器。</li><li>网页保留 /api/compose 和 /api/llm/status。自有跨域服务需实现芽音协议并允许当前网站来源；在线静态版没有内置模型后端。</li><li>先检查配置，再保存。输入描述后主动生成一版；审核音符、保留或应用。配置有效不代表凭据、额度或音乐质量已通过真实调用。</li></ol></details><div class="modal-notice">网页没有密钥输入框。检查不测试认证或额度、不自动编曲；不保存检测结果作为永久连接证明。模型可能产生费用，只有你点击生成或重试才调用。停止等待会忽略迟到结果，但服务商已处理的请求不保证停止或取消计费。</div></div><div id="settings-error" class="export-progress" role="status"></div></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="save-settings">保存设置</button>');
 const root=$('.service-settings'),result=$('#service-probe-result'),check=$('#check-service'),cancel=$('#cancel-service-check');const live=()=>root.isConnected&&d.open;
 const reset=()=>{gate.cancel();if(!live())return;check.disabled=false;cancel.hidden=true;result.hidden=true;result.textContent='';$('#settings-error').textContent=''};
 d.addEventListener('close',()=>gate.cancel(),{once:true});
 for(const field of ['settings-endpoint','settings-model','settings-status'])$('#'+field).oninput=reset;
 $('#settings-mode').onchange=e=>{reset();$('#llm-settings').hidden=e.target.value!=='llm'};
 cancel.onclick=()=>{reset();result.hidden=false;result.textContent='已停止检查。没有生成或发送工程。'};
 check.onclick=async()=>{if(gate.current)return;const endpoint=$('#settings-endpoint').value.trim()||'/api/compose',status=$('#settings-status').value.trim();if(!status){result.hidden=false;result.textContent='请填写该服务提供的状态地址；没有状态接口也可以保存并手动生成。';return}const ticket=gate.begin(8000);check.disabled=true;cancel.hidden=false;result.hidden=false;result.textContent='只读取服务状态，未发送工程，也没有调用模型…';try{const state=await probeService(endpoint,status,{base:location.href,signal:ticket.signal});if(!live()||!gate.isCurrent(ticket))return;result.innerHTML=`<h3>${state.ready?'配置检查通过 · 尚未真实调用':'服务可达 · 模型配置未就绪'}</h3><div class="service-checks"><span>芽音协议 v1</span><span>地址 / 凭据格式：${labels[state.checks.endpoint]}</span><span>模型名称：${labels[state.checks.model]}</span><span>服务端密钥：${state.apiKeyPresent?'已设置（不回传）':'未设置（本机免鉴权服务可选）'}</span></div><p>服务声明：最多 ${state.limits.maxBars} 小节 / ${state.limits.maxGeneratedNotes} 个生成音符，单请求 ${Math.round(state.limits.maxProjectBytes/1000000)} MB，等待 ${Math.round(state.limits.timeoutMs/1000)} 秒，同时 ${state.limits.maxConcurrent} 条。</p><small>这是配置与协议检查，不是实际模型 / 认证 / 额度测试。${state.ready?'保存后仍需主动生成，再审核候选。':'在服务端完成配置并重启后重新检查；离线创作不受影响。'}</small>`}catch(e){if(!live()||!gate.isCurrent(ticket))return;result.textContent=e.name==='TimeoutError'?'状态检查超时。没有调用模型或发送工程。':e instanceof ServiceError?e.message:'状态检查失败。请检查服务地址。'}finally{if(gate.finish(ticket)&&live()){check.disabled=false;cancel.hidden=true}}};
 $('#save-settings').onclick=()=>{try{const mode=$('#settings-mode').value,endpoint=$('#settings-endpoint').value.trim()||'/api/compose',statusEndpoint=$('#settings-status').value.trim(),model=$('#settings-model').value.trim();serviceUrl(endpoint,location.href);if(statusEndpoint)serviceUrl(statusEndpoint,location.href);if(model.length>120||/[\x00-\x1f\x7f]/.test(model))throw new ServiceError('input');save({mode,endpoint,statusEndpoint,model});gate.cancel();d.close();toast(mode==='offline'?'已切换到离线生成。':'设置已保存；没有自动调用模型。点生成才发送描述与音符。')}catch(e){$('#settings-error').textContent=e.message}};
 };
}
